Object.entries(passwordManagementTranslations).forEach(([lang, entries]) => Object.assign(dict[lang] || (dict[lang] = {}), entries));

const textNodeSources = new WeakMap<Text, string>();

function translateString(value: string, lang: string) {
  if (lang === 'en' || !value.trim()) return value;
  const map = dict[lang] || {};
  if (map[value]) return map[value];
  const lowerKey = value.toLowerCase();
  const caseMatch = Object.keys(map).find(k => k.toLowerCase() === lowerKey);
  if (caseMatch) {
    const translated = map[caseMatch];
    return value === value.toUpperCase() ? translated.toUpperCase() : translated;
  }
  let result = value;
  Object.keys(map).sort((a,b)=>b.length-a.length).forEach(k=>{
    if (result.includes(k)) result = result.split(k).join(map[k]);
  });
  // Catch residual standalone English UI words that were not present as full phrases.
  
  return result;
}

function convertPrices(value: string) {
  const currency = localStorage.getItem('tamp-currency') || 'USD';
  const meta = currencyMeta[currency] || currencyMeta.USD;
  const rate = rates[currency] ?? 1;
  return value.replace(/\$(\d[\d,]*(?:\.\d+)?)/g, (_, raw) => {
    const amount = Number(String(raw).replace(/,/g, ''));
    const converted = amount * rate;
    const formatted = new Intl.NumberFormat(meta.locale, { minimumFractionDigits: meta.decimals, maximumFractionDigits: meta.decimals }).format(Math.round(converted));
    return `${meta.symbol}${formatted}`;
  });
}

function translateResiduals(entries: Array<{node: Text; original: string}>, lang: string) {
  if (!entries.length || lang === 'en') return;
  // v45: normal rendering is fully deterministic. No network translation calls are made.
  // Residual text is translated by the phrase/word dictionary above; unknown values are
  // deliberately left unchanged rather than making an unbounded API call during rendering.
  entries.forEach(x => {
    const translated = translateString(x.original, lang);
    if (translated !== x.original) x.node.nodeValue = convertPrices(translated);
  });
}

function translateTree(root: HTMLElement, lang: string) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes: Text[] = [];
  let node: Node | null;
  while ((node = walker.nextNode())) nodes.push(node as Text);
  const residuals: Array<{node:Text;original:string}> = [];
  nodes.forEach(n => {
    const parent = n.parentElement;
    if (!parent || ['SCRIPT','STYLE'].includes(parent.tagName) || parent.closest('[data-no-translate]')) return;
    const current = n.nodeValue ?? '';
    const original = textNodeSources.get(n) ?? current;
    textNodeSources.set(n, original);
    const translated=translateString(original, lang);
    n.nodeValue = convertPrices(translated);
    const cls=parent.className || '';
    const protectedName=/product-name|brand-name|merchant-name|account-name/.test(String(cls));
    if(lang!=='en' && translated===original && original.trim().length>=4 && !protectedName && !/^[\d\s$€£₦₵₹.,:%+()/#-]+$/.test(original.trim())) residuals.push({node:n,original});
  });
  root.querySelectorAll<HTMLElement>('[placeholder],[aria-label],[title]').forEach(el => {
    if (el.closest('[data-no-translate]')) return;
    for (const attr of ['placeholder','aria-label','title']) {
      const value = el.getAttribute(attr); if (!value) continue;
      const original = el.getAttribute(`data-tamp-original-${attr}`) ?? value;
      el.setAttribute(`data-tamp-original-${attr}`, original);
      el.setAttribute(attr, translateString(original, lang));
    }
  });
  void translateResiduals(residuals,lang);
}


