export function LocalizedPrice({ amount, className = '' }: { amount: number; className?: string }) {
  const [currency, setCurrency] = useStateCurrency();
  const meta = currencyMeta[currency] || currencyMeta.USD;
  const value = amount * (rates[currency] ?? 1);
  const formatted = new Intl.NumberFormat(meta.locale, { minimumFractionDigits: meta.decimals, maximumFractionDigits: meta.decimals }).format(Math.round(value));
  return <span className={className} data-base-price={amount}>{meta.symbol}{formatted}</span>;
}

export function useLang() {
  const [lang, setLang] = useState('en');
  useEffect(() => {
    const read = () => setLang(localStorage.getItem('tamp-language') || 'en');
    read(); window.addEventListener('tamp-preferences', read);
    return () => window.removeEventListener('tamp-preferences', read);
  }, []);
  return lang as Lang;
}

function useStateCurrency() {
  const [currency, setCurrency] = useState('USD');
  useEffect(() => {
    const read = () => setCurrency(localStorage.getItem('tamp-currency') || 'USD');
    read(); window.addEventListener('storage', read); window.addEventListener('tamp-preferences', read);
    return () => { window.removeEventListener('storage', read); window.removeEventListener('tamp-preferences', read); };
  }, []);
  return [currency, setCurrency] as const;
}

export function LocalizationLayer() {
  useEffect(() => {
    const run = () => {
      const lang = localStorage.getItem('tamp-language') || 'en';
      document.documentElement.lang = lang;
      document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
      document.documentElement.dataset.language = lang;
      translateTree(document.body, lang);
    };
    run();
    fetch('/api/pricing/rates?base=USD').then(r => r.ok ? r.json() : null).then(data => {
      if (data?.rates) { Object.entries(data.rates as Record<string, number>).forEach(([code, rate]) => { if (Number.isFinite(rate)) rates[code] = Number(rate); }); run(); }
    }).catch(() => undefined);
    const observer = new MutationObserver(() => requestAnimationFrame(run));
    observer.observe(document.body, { childList: true, subtree: true });
    window.addEventListener('tamp-preferences', run);
    return () => { observer.disconnect(); window.removeEventListener('tamp-preferences', run); };
  }, []);
  return null;
}




